package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code membershipNumber} before it is saved. The number is formatted
 * {@code <customerCode>-M<YY>}, where {@code customerCode} is the owner's customer code and
 * {@code YY} is the last two digits of the {@code registrationDate} year, zero-padded
 * (e.g. {@code NSW-3F1A9C2B-M26}). Runs after {@link AssignCustomerCode} has set the customer code
 * and {@link BuildOwner} has set the registration date, so both inputs are present. Mutates the
 * entity in place so {@link SaveOwner} persists it.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
 * holiday advances to the next non-holiday weekday, a plain weekday is left unchanged. Applied to
 * the <em>effective</em> registration date — whether supplied on the request or defaulted to the
 * server date — so that the persisted {@code registrationDate} always falls on a business day and
 * every value derived from it (the membership number's year segment in
 * {@link AssignMembershipNumber}, the per-day create-limit bucket in {@link CheckOwnerDailyLimit})
 * is computed from the same adjusted date.
 */
final class BusinessDay {

    /** Fixed public-holiday calendar; a date on this list is not a business day. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
            LocalDate.of(2026, 1, 1),
            LocalDate.of(2026, 1, 26),
            LocalDate.of(2026, 4, 25),
            LocalDate.of(2026, 12, 25),
            LocalDate.of(2026, 12, 28));

    private BusinessDay() {
    }

    /** The given date if it is a business day, otherwise the next non-weekend, non-holiday date. */
    static LocalDate rollForward(LocalDate date) {
        while (!isBusinessDay(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
    }
}
package org.springframework.samples.petclinic.util;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Scores an owner's {@code membershipPoints} and maps them to a numeric {@code membershipLevel}.
 * Points start at 0 and accrue from the owner's factors: +2 when an email is present, +1 when its
 * {@code namesakeCount} is 0, +2 for a household of 3 or more members, and +3 when tenure — the days
 * from its {@code registrationDate} to today — exceeds 365. The total maps to a level: 1 for 0-1
 * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
 *
 * <p>The household factor needs the number of owners sharing the household, which only the
 * repository knows; {@link #pointsOf(Owner)} scores the owner's own fields with no household bump,
 * while {@link #pointsOf(Owner, int)} adds it once the caller supplies the household size.
 */
public final class MembershipLevel {

    /** Points awarded when the owner has an email. */
    private static final int EMAIL_POINTS = 2;

    /** Points awarded when the owner shares its name with no existing owner. */
    private static final int UNIQUE_NAME_POINTS = 1;

    /** Points awarded when the owner's household has {@value #HOUSEHOLD_THRESHOLD} or more members. */
    private static final int HOUSEHOLD_POINTS = 2;

    /** Points awarded when the owner's tenure exceeds {@value #TENURE_DAYS} days. */
    private static final int TENURE_POINTS = 3;

    /** Household size, in members, at or above which {@link #HOUSEHOLD_POINTS} is awarded. */
    private static final int HOUSEHOLD_THRESHOLD = 3;

    /** Tenure, in days, that an owner must exceed to earn {@link #TENURE_POINTS}. */
    private static final long TENURE_DAYS = 365;

    private MembershipLevel() {
    }

    /** Membership points from the owner's own fields, without the household factor. */
    public static int pointsOf(Owner owner) {
        return pointsOf(owner, 0);
    }

    /** Membership points including +2 when {@code householdSize} is 3 or more. */
    public static int pointsOf(Owner owner, int householdSize) {
        int points = 0;
        String email = owner.getEmail();
        if (email != null && !email.isEmpty()) {
            points += EMAIL_POINTS;
        }
        Integer namesakeCount = owner.getNamesakeCount();
        if (namesakeCount != null && namesakeCount == 0) {
            points += UNIQUE_NAME_POINTS;
        }
        if (householdSize >= HOUSEHOLD_THRESHOLD) {
            points += HOUSEHOLD_POINTS;
        }
        if (exceedsTenure(owner.getRegistrationDate())) {
            points += TENURE_POINTS;
        }
        return points;
    }

    /** Maps {@code points} to a level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
    public static int levelOf(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /** Whether {@code registrationDate} is more than {@value #TENURE_DAYS} days before today. */
    private static boolean exceedsTenure(LocalDate registrationDate) {
        if (registrationDate == null) {
            return false;
        }
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_DAYS;
    }
}
package org.springframework.samples.petclinic.util;

import java.time.LocalDate;
import java.time.Period;

/**
 * Derives an owner's {@code ageBand} from its {@code birthDate} as of its {@code registrationDate}.
 * The band is {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64 inclusive, and
 * {@code SENIOR} at 65 or older. There is no band when no birth date was supplied.
 */
public final class AgeBand {

    /** Upper (exclusive) age for the MINOR band. */
    private static final int ADULT_AGE = 18;

    /** Lower (inclusive) age for the SENIOR band. */
    private static final int SENIOR_AGE = 65;

    private AgeBand() {
    }

    /**
     * Returns the age band for an owner born on {@code birthDate} as of {@code registrationDate}, or
     * {@code null} when {@code birthDate} is absent.
     */
    public static String of(LocalDate birthDate, LocalDate registrationDate) {
        if (birthDate == null || registrationDate == null) {
            return null;
        }
        int years = Period.between(birthDate, registrationDate).getYears();
        if (years < ADULT_AGE) {
            return "MINOR";
        }
        if (years < SENIOR_AGE) {
            return "ADULT";
        }
        return "SENIOR";
    }
}

